      border-radius: 24px;
      box-shadow: var(--shadow);
      padding: 1.5rem;
    }

    .form-field {
      background: var(--panel-alt);
      border: 1px solid var(--border);
      border-radius: 20px;
      padding: 1.25rem;
    }

