      border-color: transparent;
    }

    .option:has(input:checked) {
      border-color: var(--border-strong);
      background: rgba(138, 180, 255, 0.12);
    }

    .form-actions {
      margin-top: 1.25rem;
      display: flex;
      gap: 0.75rem;
      align-items: center;
      flex-wrap: wrap;
    }

