      background: linear-gradient(180deg, var(--accent-strong), var(--accent));
      color: #08111f;
      font: inherit;
      font-weight: 700;
      cursor: pointer;
      box-shadow: 0 10px 22px rgba(138, 180, 255, 0.25);
      transition: transform 0.2s ease, box-shadow 0.2s ease;
    }

    button:hover {
      transform: translateY(-1px);
      box-shadow: 0 14px 28px rgba(138, 180, 255, 0.3);
    }

    button:focus-visible {
      outline: 3px solid var(--accent-strong);
      outline-offset: 3px;
    }

    button:active {
      transform: translateY(0);
    }

    .status {
      min-height: 1.5rem;
      margin: 0;
      color: var(--success);
      font-weight: 600;
    }

    .status.is-error {
      color: var(--error);
    }

    @media (max-width: 480px) {
      main {
        padding-inline: 0.75rem;
      }

      .page-shell,
      form,
      .form-field {
        padding: 1rem;
      }
    }

    @media (forced-colors: active) {
      .skip-link,
      form,
      .form-field,
      .option,
      button {
        forced-color-adjust: auto;
        background: Canvas;
        color: CanvasText;
        border-color: ButtonBorder;
        box-shadow: none;
      }

      .skip-link:focus,
      .option:has(input:focus-visible),
      button:focus-visible {
        outline-color: Highlight;
      }

      .option:has(input:checked) {
        border-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="page-shell" aria-labelledby="page-title">
      <div class="intro">
        <h1 id="page-title">Notification Preferences</h1>
        <p>Choose your preferred notification channel below.</p>
      </div>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-help notification-status">
            <legend>How do you prefer to receive notifications? <span class="required" aria-hidden="true">*</span></legend>
            <p class="help-text" id="notification-help">Select one option before submitting the form.</p>

            <div class="options" role="radiogroup" aria-label="Notification delivery method">
              <label class="option" for="email">
                <input type="radio" id="email" name="notification-preference" value="Email" required>
                <span>Email</span>
              </label>
              <label class="option" for="sms">
                <input type="radio" id="sms" name="notification-preference" value="SMS">
                <span>SMS</span>
              </label>
              <label class="option" for="push">
                <input type="radio" id="push" name="notification-preference" value="Push Notifications">
                <span>Push Notifications</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-actions">
          <button type="submit">Submit</button>
          <p class="status" id="notification-status" aria-live="polite"></p>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.getElementById('notification-form');
    const radios = Array.from(form.querySelectorAll('input[type="radio"][name="notification-preference"]'));
    const status = document.getElementById('notification-status');

    function updateValidityState() {
      const hasSelection = radios.some((radio) => radio.checked);
      radios.forEach((radio) => {
        radio.setAttribute('aria-invalid', hasSelection ? 'false' : 'true');
      });
    }

    radios.forEach((radio) => {
      radio.addEventListener('change', () => {
        updateValidityState();
        status.textContent = '';
        status.classList.remove('is-error');
      });
    });

